// GENERATED by scripts/build-sync-function.mjs. Edit handler.ts.txt or app/src/lib/poSheetParser.ts instead.
// Supabase Edge Function: receives the PO workbook from the Google Sheet's
// Apps Script and imports it, exactly like the app's "Import from Excel".
// Protected by a shared secret (SYNC_SECRET), set under Edge Functions → Secrets.
// Turn OFF "Verify JWT" for this function: the secret is the check.
import { createClient } from 'npm:@supabase/supabase-js@2';

// Turns the company's PO-list workbook (Google Sheets → .xlsx) into clean rows
// for the import_po_rows() database function. Pure TypeScript, no React, so it
// runs the same on the phone and in Node tests.
//
// Handles what the real sheet contains:
//  - one tab per financial year ("PO-23-24", "PO-24-25", ...); other tabs are skipped
//  - the header row is found by its titles, so moved/added columns are fine
//  - job nos written as 24/1000 or 24-1000
//  - dates as real dates, "27.03.2024", "09.08.23", or Excel serial numbers
//  - several invoice nos / dates in one cell ("23/051 23/059"), credit notes ignored
//  - tax written as 0.18 or 18
//  - free-text status ("Complete", "Dsp-02_Complete", "Cancel", "HOLD")
import * as XLSX from 'npm:xlsx@0.18.5';
type WorkBook = XLSX.WorkBook;
type WorkSheet = XLSX.WorkSheet;

export type ImportInvoice = { no: string; date: string | null };

export type ImportRow = {
  sheet: string;
  sheet_row: number;
  job_no: string;
  line_no: number;
  customer: string;
  customer_po_no: string | null;
  po_date: string | null;
  delivery_date: string | null;
  tpi: boolean;
  description: string;
  item_code: string | null;
  qty: number | null;
  rate: number | null;
  basic_value: number | null;
  pf_pct: number | null;
  pf_value: number | null;
  freight_pct: number | null;
  freight_value: number | null;
  taxable_value: number | null;
  gst_pct: number | null;
  gst_value: number | null;
  total_value: number | null;
  invoices: ImportInvoice[];
  status_text: string | null;
  finance_notes: string | null;
};

export type ParseIssue = { sheet: string; row: number; message: string; level: 'warning' | 'error' };

export type ParseResult = {
  rows: ImportRow[];
  issues: ParseIssue[];
  sheets: { name: string; rows: number; jobs: number; skipped?: string }[];
};

// Column titles we look for (lower-case, spaces squashed). First match wins.
const COLUMNS: Record<string, string[]> = {
  job_no: ['sepl p.o no.', 'sepl po no', 'sepl p.o no', 'job no'],
  customer: ['company', 'customer'],
  tpi: ['tpi'],
  customer_po_no: ['p.o no.', 'po no', 'p.o no'],
  po_date: ['p.o. date', 'po date'],
  delivery_date: ['delivery date'],
  description: ['items', 'item', 'description'],
  item_code: ['item code'],
  qty: ['po qty.', 'po qty', 'qty'],
  rate: ['item value', 'rate'],
  basic_value: ['item total value'],
  pf_pct: ['p & f %', 'p&f %'],
  pf_value: ['p&f value', 'p & f value'],
  freight_pct: ['freight %'],
  freight_value: ['freight value'],
  taxable_value: ['total basic value'],
  gst_pct: ['tax %', 'gst %'],
  gst_value: ['gst amount'],
  total_value: ['final item value (inc. all)', 'final item value'],
  invoice_no: ['inv no', 'invoice no'],
  invoice_date: ['date', 'inv date', 'invoice date'],
  status: ['completion sattus', 'completion status', 'status'],
  sale_notes: ['total sale'],
};

const norm = (v: unknown) => String(v ?? '').replace(/\s+/g, ' ').trim().toLowerCase();
const text = (v: unknown) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  return s === '' || s === '-' || s === '--' ? null : s;
};

export function isYearSheet(name: string) {
  return /^po[\s-]*\d{2}[\s-]+\d{2}$/i.test(name.trim());
}

export function normalizeJobNo(v: unknown): string | null {
  const s = String(v ?? '').trim();
  const m = s.match(/^(\d{2})\s*[-/]\s*(\d{3,5})$/);
  return m ? `${m[1]}-${m[2]}` : null;
}

function isoDate(y: number, m: number, d: number): string | null {
  if (y < 100) y += 2000;
  if (m < 1 || m > 12 || d < 1 || d > 31 || y < 2000 || y > 2100) return null;
  const dt = new Date(Date.UTC(y, m - 1, d));
  if (dt.getUTCMonth() !== m - 1) return null;
  return dt.toISOString().slice(0, 10);
}

/** Parse one date value. Returns ISO yyyy-mm-dd or null. */
export function parseDate(v: unknown): string | null {
  if (v == null || v === '') return null;
  if (v instanceof Date && !isNaN(v.getTime())) {
    // SheetJS gives local-midnight dates; use local parts
    return isoDate(v.getFullYear(), v.getMonth() + 1, v.getDate());
  }
  if (typeof v === 'number') {
    if (v < 30000 || v > 80000) return null; // not a plausible Excel serial
    const dt = new Date(Date.UTC(1899, 11, 30) + Math.floor(v) * 86400000); // Excel day 0
    return isoDate(dt.getUTCFullYear(), dt.getUTCMonth() + 1, dt.getUTCDate());
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{2}|\d{4})$/);
  if (m) return isoDate(+m[3], +m[2], +m[1]);
  m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return isoDate(+m[1], +m[2], +m[3]);
  return null;
}

/** All dates found inside a free-text cell, in order. */
export function parseDates(v: unknown): string[] {
  if (v == null || v === '') return [];
  if (typeof v !== 'string') {
    const d = parseDate(v);
    return d ? [d] : [];
  }
  const out: string[] = [];
  for (const m of v.matchAll(/(\d{1,2})\.(\d{1,2})\.(\d{4}|\d{2})(?!\d)/g)) {
    const d = isoDate(+m[3], +m[2], +m[1]);
    if (d) out.push(d);
  }
  return out;
}

/** Invoice numbers like 23/049 or 25/1034 inside a free-text cell. Credit notes (CR-13) are skipped. */
export function parseInvoiceNos(v: unknown): string[] {
  if (v == null) return [];
  const s = String(v);
  const out: string[] = [];
  for (const m of s.matchAll(/(?<![\d/])(\d{2})\/(\d{2,4})(?![\d/])/g)) out.push(`${m[1]}/${m[2]}`);
  return [...new Set(out)];
}

/** Invoice numbers and credit notes in the order they appear (credit notes as "CR"). */
function invoiceCellTokens(v: unknown): string[] {
  if (v == null) return [];
  const out: string[] = [];
  for (const m of String(v).matchAll(/(?<![\d/])(\d{2})\/(\d{2,4})(?![\d/])|\bCR\b[\s.\-]*(?:No\.?)?\s*-?\d+/gi))
    out.push(m[1] ? `${m[1]}/${m[2]}` : 'CR');
  return out;
}

export function parseNumber(v: unknown): number | null {
  if (v == null || v === '') return null;
  if (typeof v === 'number') return isFinite(v) ? v : null;
  const s = String(v).replace(/[,\s₹]/g, '').replace(/^rs\.?/i, '');
  if (!/^-?\d*\.?\d+$/.test(s)) return null;
  return Number(s);
}

function pct(v: unknown): number | null {
  const n = parseNumber(typeof v === 'string' ? v.replace('%', '') : v);
  if (n == null) return null;
  return n > 0 && n <= 1 ? Math.round(n * 10000) / 100 : n; // 0.18 → 18
}

function findHeader(grid: unknown[][]): { row: number; cols: Record<string, number> } | null {
  for (let r = 0; r < Math.min(grid.length, 15); r++) {
    const cells = (grid[r] ?? []).map(norm);
    if (!cells.includes('company') || !cells.some((c) => c === 'items' || c === 'item')) continue;
    const cols: Record<string, number> = {};
    for (const [key, names] of Object.entries(COLUMNS)) {
      for (const name of names) {
        const i = cells.findIndex((c, idx) => c === name && !Object.values(cols).includes(idx));
        if (i >= 0) { cols[key] = i; break; }
      }
    }
    return { row: r, cols };
  }
  return null;
}

export function parseSheet(name: string, ws: WorkSheet, issues: ParseIssue[]): ImportRow[] {
  const grid = XLSX.utils.sheet_to_json<unknown[]>(ws, { header: 1, raw: true, defval: null, blankrows: true });
  const header = findHeader(grid);
  if (!header) {
    issues.push({ sheet: name, row: 0, level: 'error', message: 'Could not find the header row (COMPANY / ITEMS)' });
    return [];
  }
  const { cols } = header;
  for (const need of ['job_no', 'customer', 'description']) {
    if (cols[need] == null) {
      issues.push({ sheet: name, row: header.row + 1, level: 'error', message: `Missing column: ${COLUMNS[need][0].toUpperCase()}` });
      return [];
    }
  }
  const get = (row: unknown[], key: string) => (cols[key] == null ? null : row[cols[key]]);

  const out: ImportRow[] = [];
  const lineCounter = new Map<string, number>();
  for (let r = header.row + 1; r < grid.length; r++) {
    const row = grid[r] ?? [];
    const rawJob = get(row, 'job_no');
    if (rawJob == null || String(rawJob).trim() === '') continue; // blank / formula-only rows
    const excelRow = r + 1;
    const job_no = normalizeJobNo(rawJob);
    if (!job_no) {
      issues.push({ sheet: name, row: excelRow, level: 'warning', message: `Skipped: job no "${rawJob}" is not like 25-1061` });
      continue;
    }
    const description = text(get(row, 'description'));
    if (!description) {
      issues.push({ sheet: name, row: excelRow, level: 'warning', message: `Skipped: ${job_no} has no item description` });
      continue;
    }
    const customer = text(get(row, 'customer'));
    if (!customer) {
      issues.push({ sheet: name, row: excelRow, level: 'warning', message: `Skipped: ${job_no} has no company` });
      continue;
    }

    const line_no = (lineCounter.get(job_no) ?? 0) + 1;
    lineCounter.set(job_no, line_no);

    const rawPoDate = get(row, 'po_date');
    const rawDel = get(row, 'delivery_date');
    const po_date = parseDate(rawPoDate);
    const delivery_date = parseDate(rawDel);
    if (rawPoDate != null && text(rawPoDate) && !po_date)
      issues.push({ sheet: name, row: excelRow, level: 'warning', message: `${job_no}: PO date "${rawPoDate}" not understood, left blank` });
    if (rawDel != null && text(rawDel) && !delivery_date)
      issues.push({ sheet: name, row: excelRow, level: 'warning', message: `${job_no}: delivery date "${rawDel}" not understood, left blank` });

    const invNos = parseInvoiceNos(get(row, 'invoice_no'));
    const invDates = parseDates(get(row, 'invoice_date'));
    // Credit notes in the invoice cell ("25/030 CR No.08 25/055") usually have their own date in the
    // date cell, so match dates by position among all entries when the counts line up.
    const invTokens = invoiceCellTokens(get(row, 'invoice_no'));
    const invoices = invNos.map((no, i) => {
      const pos = invTokens.length === invDates.length ? invTokens.indexOf(no) : -1;
      return { no, date: (pos >= 0 ? invDates[pos] : invDates[i]) ?? invDates[invDates.length - 1] ?? null };
    });

    const status = text(get(row, 'status'));
    const sale = text(get(row, 'sale_notes'));
    const invRaw = text(get(row, 'invoice_no'));
    const notes = [
      status && `Status: ${status}`,
      sale && `Notes: ${sale}`,
      invRaw && invNos.join(' ') !== invRaw && `Invoice cell: ${invRaw}`,
    ].filter(Boolean).join(' | ');

    const codeRaw = get(row, 'item_code');
    const item_code = typeof codeRaw === 'number' ? String(Math.round(codeRaw)) : text(codeRaw)?.replace(/'$/, '') ?? null;

    out.push({
      sheet: name,
      sheet_row: excelRow,
      job_no,
      line_no,
      customer: customer.toUpperCase(),
      customer_po_no: text(get(row, 'customer_po_no')),
      po_date,
      delivery_date,
      tpi: norm(get(row, 'tpi')) === 'tpi',
      description,
      item_code,
      qty: parseNumber(get(row, 'qty')),
      rate: parseNumber(get(row, 'rate')),
      basic_value: parseNumber(get(row, 'basic_value')),
      pf_pct: pct(get(row, 'pf_pct')),
      pf_value: parseNumber(get(row, 'pf_value')),
      freight_pct: pct(get(row, 'freight_pct')),
      freight_value: parseNumber(get(row, 'freight_value')),
      taxable_value: parseNumber(get(row, 'taxable_value')),
      gst_pct: pct(get(row, 'gst_pct')),
      gst_value: parseNumber(get(row, 'gst_value')),
      total_value: parseNumber(get(row, 'total_value')),
      invoices,
      status_text: status,
      finance_notes: notes || null,
    });
  }
  return out;
}

export function parseWorkbook(wb: WorkBook): ParseResult {
  const issues: ParseIssue[] = [];
  const rows: ImportRow[] = [];
  const sheets: ParseResult['sheets'] = [];
  const seenJobs = new Map<string, string>();
  for (const name of wb.SheetNames) {
    if (!isYearSheet(name)) {
      sheets.push({ name, rows: 0, jobs: 0, skipped: 'not a year sheet (PO-yy-yy)' });
      continue;
    }
    const sheetRows = parseSheet(name, wb.Sheets[name], issues);
    // a job number should live in one year sheet only
    const kept = sheetRows.filter((r) => {
      const other = seenJobs.get(r.job_no);
      if (other && other !== name) {
        issues.push({ sheet: name, row: r.sheet_row, level: 'warning', message: `Skipped: ${r.job_no} already imported from ${other}` });
        return false;
      }
      return true;
    });
    kept.forEach((r) => seenJobs.set(r.job_no, name));
    rows.push(...kept);
    sheets.push({ name, rows: kept.length, jobs: new Set(kept.map((r) => r.job_no)).size });
  }
  return { rows, issues, sheets };
}

/** Read a workbook from base64 (phone) or a Buffer/Uint8Array (Node). */
export function readWorkbook(data: string | Uint8Array, type: 'base64' | 'array' = 'base64'): WorkBook {
  return XLSX.read(data, { type, cellDates: true });
}

/** Rows as the database function expects them (drops sheet bookkeeping). */
export function toDbRows(rows: ImportRow[]) {
  return rows.map(({ sheet, sheet_row, ...r }) => r);
}


const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } });

function sameSecret(a: string, b: string) {
  if (!a || !b || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

Deno.serve(async (req) => {
  if (req.method !== 'POST') return json({ error: 'POST only' }, 405);
  const secret = Deno.env.get('SYNC_SECRET') ?? '';
  if (secret.length < 24) return json({ error: 'SYNC_SECRET is not set on the server' }, 500);
  if (!sameSecret(req.headers.get('x-sync-secret') ?? '', secret)) return json({ error: 'Wrong sync key' }, 401);

  const admin = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);
  const log = (ok: boolean, summary: unknown, error?: string) =>
    admin.from('sync_log').insert({ ok, summary, error: error ?? null });

  try {
    const body = await req.json();
    if (typeof body?.xlsx_base64 !== 'string') return json({ error: 'Missing xlsx_base64' }, 400);
    const parsed = parseWorkbook(readWorkbook(body.xlsx_base64, 'base64'));
    if (!parsed.rows.length) {
      await log(false, { sheets: parsed.sheets }, 'No PO rows found');
      return json({ error: 'No PO rows found. Are the tabs still named like PO-26-27?', sheets: parsed.sheets }, 422);
    }
    const { data, error } = await admin.rpc('import_po_rows', { p_rows: toDbRows(parsed.rows) });
    if (error) throw new Error(error.message);
    const summary = { ...data, rows: parsed.rows.length, warnings: parsed.issues.length };
    await log(true, summary);
    return json({ ok: true, ...summary, issues: parsed.issues.slice(0, 30) });
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    await log(false, null, msg);
    return json({ error: msg }, 500);
  }
});
